using GestaoClientes.Application;using GestaoClientes.Domain.Enums;using Microsoft.AspNetCore.Mvc;
namespace GestaoClientes.Api.Controllers;
[ApiController][Route("api/clientes")] public class ClientesController(ClienteService service):ControllerBase { [HttpPost] public async Task<IActionResult> Criar(CriarClienteRequest r){var c=await service.CriarAsync(r);return CreatedAtAction(nameof(Obter),new{id=c.Id},c);}[HttpGet] public Task<Paginado<ClienteResponse>> Listar([FromQuery]int pagina=1,[FromQuery]int tamanhoPagina=10,[FromQuery]string? nome=null,[FromQuery]string? cpf=null,[FromQuery]StatusCliente? status=null)=>service.ListarAsync(pagina,tamanhoPagina,nome,cpf,status);[HttpGet("{id:int}")]public async Task<ClienteResponse> Obter(int id)=>await service.ObterAsync(id);[HttpPut("{id:int}")]public async Task<IActionResult> Atualizar(int id,AtualizarClienteRequest r){await service.AtualizarAsync(id,r);return NoContent();}[HttpDelete("{id:int}")]public async Task<IActionResult> Inativar(int id){await service.InativarAsync(id);return NoContent();}[HttpPut("{id:int}/ativar")]public async Task<IActionResult> Ativar(int id){await service.AtivarAsync(id);return NoContent();}[HttpGet("{id:int}/enderecos")]public Task<IReadOnlyCollection<EnderecoResponse>> Enderecos(int id)=>service.EnderecosAsync(id);[HttpPost("{id:int}/enderecos")]public async Task<IActionResult> AdicionarEndereco(int id,EnderecoRequest r){await service.AdicionarEnderecoAsync(id,r);return NoContent();}[HttpPut("{id:int}/enderecos/{enderecoId:int}")]public async Task<IActionResult> AtualizarEndereco(int id,int enderecoId,EnderecoRequest r){await service.AtualizarEnderecoAsync(id,enderecoId,r);return NoContent();}[HttpDelete("{id:int}/enderecos/{enderecoId:int}")]public async Task<IActionResult> RemoverEndereco(int id,int enderecoId){await service.RemoverEnderecoAsync(id,enderecoId);return NoContent();}[HttpPut("{id:int}/enderecos/{enderecoId:int}/principal")]public async Task<IActionResult> Principal(int id,int enderecoId){await service.PrincipalAsync(id,enderecoId);return NoContent();}}
